import{z as E,x as d,o,c,q as s,j as t,D as a,d as i,s as l,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"交叉编译与三元组","description":"","frontmatter":{"title":"交叉编译与三元组","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cross-compile-triple.md","filePath":"cs/cross-compile-triple.md","lastUpdated":1791413859000}'),A={name:"cs/cross-compile-triple.md"};function p(B,e,u,m,_,h){const r=d("Mermaid");return o(),c("div",null,[e[2]||(e[2]=s('<h1 id="交叉编译与三元组" tabindex="-1">交叉编译与三元组 <a class="header-anchor" href="#交叉编译与三元组" aria-label="Permalink to &quot;交叉编译与三元组&quot;">​</a></h1><div class="epigraph"><p>三元组写出 CPU–厂商–OS–ABI。交叉编译在主机上为另一三元组生成 ELF，系统根、头文件与库必须匹配目标，而不是主机。</p><footer>—— 据 GNU Autoconf 三元组惯例；Clang `--target`；交叉工具链实践整理</footer></div><p>上一课<a href="/cs/exec-loading-elf">ELF 加载</a> 假定二进制已是本机 ABI。缺口是<strong>为另一台机器生成</strong>：<code>riscv64-unknown-linux-gnu</code>。后端与链接课序在此收束。下一单元运行时与 VM。本课钉 sysroot 与不要混链主机 libc。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>编译器默认主机三元组。交叉：<code>--target</code> 选<a href="/cs/target-description">目标描述</a>，链接器选目标 <code>ld</code>、目标 <code>libc</code>。缺口是<strong>工具链前缀与 sysroot</strong>，不是内核 mmap。</p><p><code>build/host/target</code> 三词：Autoconf 的 Canadian cross 点名。日常：host=本机，target=嵌入式。</p><h3 id="三元组不是「isa-别名」" tabindex="-1">三元组不是「ISA 别名」 <a class="header-anchor" href="#三元组不是「isa-别名」" aria-label="Permalink to &quot;三元组不是「ISA 别名」&quot;">​</a></h3><p><code>x86_64-linux-gnu</code> 与 <code>x86_64-linux-musl</code> 同一 ISA，libc/ABI 不同，不能混 <code>.so</code>。不要只看 <code>uname -m</code>。</p><p><span class="marginnote">GNU config.sub。Clang/LLVM 三元组。本课不写发行版如何打 rootfs。</span></p><p><span class="marginnote">术语翻译：三元组就是给「目标机器」写的完整地址：CPU 架构-厂商-系统-ABI。<code>riscv64-unknown-linux-gnu</code> 读作「RISC-V 64 位、厂商无所谓、Linux 系统、GNU ABI」——四个字段各管一件事，缺一个都可能链错库。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>--sysroot</code> 指向目标根。pkg-config 要目标的。QEMU user 可跑目标 ELF 做测试。表调度延迟模型应按目标微架构，不是主机。</p>',12)),(o(),t(n,null,{default:a(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%22%5D%20--%3E%20CC%5B%22%E4%BA%A4%E5%8F%89%E7%BC%96%E8%AF%91%E5%99%A8%22%5D%0A%20%20SYS%5B%22%E7%9B%AE%E6%A0%87%20sysroot%22%5D%20--%3E%20CC%0A%20%20CC%20--%3E%20ELF%5B%22%E7%9B%AE%E6%A0%87%20ELF%22%5D%0A%20%20ELF%20--%3E%20QEMU%5B%22%E6%A8%A1%E6%8B%9F%E6%88%96%E7%9C%9F%E6%9C%BA%E5%8A%A0%E8%BD%BD%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s('<p><span class="marginnote">术语翻译：sysroot 是「目标的整个文件系统塞进一个目录」——头文件在 usr/include、库在 usr/lib。<code>--sysroot</code> 让编译器找 stdio.h 和 libc 时去这个目录，而不是本机的 /usr，从而保证「看的是目标的头、链的是目标的库」。</span></p><p>与 LTO：主机跑 lto，目标后端代码生成——bitcode 是中立的，机器描述仍是目标的。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>错误：链接了 <code>/usr/lib</code> 主机库，加载时 SIGSEGV 或 ELF 类不匹配。检查：<code>file</code>、<code>readelf -h</code> 的机器字段。</p>',4)),(o(),t(n,null,{default:a(()=>[l(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20LINK%5B%22%E9%93%BE%E6%8E%A5%E6%AF%8F%E4%B8%AA%E5%BA%93%22%5D%20--%3E%20Q%7B%22%E5%BA%93%E6%9D%A5%E8%87%AA%E7%9B%AE%E6%A0%87%20sysroot%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20OK%5B%22%E7%BB%A7%E7%BB%AD%2C%20%E7%94%9F%E6%88%90%E7%9B%AE%E6%A0%87%20ELF%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%3A%20%E8%AF%AF%E9%93%BE%E4%B8%BB%E6%9C%BA%20%2Fusr%2Flib%22%7C%20BAD%5B%22%E6%8C%87%E4%BB%A4%E9%9B%86%E6%88%96%20ABI%20%E4%B8%8D%E5%8C%B9%E9%85%8D%22%5D%0A%20%20BAD%20--%3E%20SYM%5B%22%E7%97%87%E7%8A%B6%3A%20%E7%9C%9F%E6%9C%BA%E5%8A%A0%E8%BD%BD%20SIGSEGV%20%E6%88%96%20ELF%20%E7%B1%BB%E4%B8%8D%E5%8C%B9%E9%85%8D%22%5D%0A%20%20SYM%20--%3E%20CHK%5B%22%E7%94%A8%20file%20%E4%B8%8E%20readelf%20-h%20%E6%9F%A5%E6%9C%BA%E5%99%A8%E5%AD%97%E6%AE%B5%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=s('<p><span class="marginnote">常见误区：初学者容易以为「都是 x86_64 就能混用」。<code>x86_64-linux-gnu</code> 与 <code>x86_64-linux-musl</code> 是同一个 ISA、不同的 libc 与 ABI，混链照样崩；<code>uname -m</code> 只回答了三元组四个字段里的第一个。</span></p><p>多架构 Docker 不是本课重点；原理仍是三元组。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写发行构建系统。后课默认：后端输出服从三元组。下一课字节码解释器：另一类「目标」，不是 ELF 加载。</p><p>也不把三元组当 Transformer 的 tokenization。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三元组标识 ISA+OS+ABI；交叉用匹配的 sysroot。</li><li>混链主机库是经典失败。</li><li>LTO 在主机优化、在目标降码。</li><li>出处：GNU 三元组惯例；Clang <code>--target</code>；对照 ELF 加载。</li></ul>',7))])}const D=E(A,[["render",p]]);export{f as __pageData,D as default};
